#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <new>
static volatile std::size_t calls=0,bytes=0,live=0,peak=0;
struct alignas(std::max_align_t) Allocation{std::size_t bytes;};
void* operator new(std::size_t n){void*raw=std::malloc(sizeof(Allocation)+n);if(!raw)throw std::bad_alloc();auto*h=static_cast<Allocation*>(raw);h->bytes=n;calls=calls+1;bytes=bytes+n;live=live+n;if(live>peak)peak=live;return h+1;}
void operator delete(void*p)noexcept{if(p){auto*h=static_cast<Allocation*>(p)-1;live=live-h->bytes;std::free(h);}}
void operator delete(void*p,std::size_t)noexcept{operator delete(p);}
#include SOURCE
int main(int argc,char**argv){if(argc!=3)return 1;int n=std::atoi(argv[1]),mode=std::atoi(argv[2]);using UF=UnionFind;std::size_t before=live;{
 UF uf(n);std::printf("{\"sizeof_uf\":%zu,\"constructor_calls\":%zu,\"constructor_bytes\":%zu,",sizeof(UF),calls,bytes);
 if(mode==1)for(int i=0;i+1<n;i+=2)uf.unite(i,i+1);
 if(mode==2)for(int i=0;i+3<n;i+=4)for(int j=1;j<4;++j)uf.unite(i,i+j);
 if(mode==3)for(int i=1;i<n;++i)uf.unite(0,i);
 std::size_t old_calls=calls,old_bytes=bytes,old_live=live;peak=live;{
 auto groups=uf.groups();std::size_t sum=0;for(const auto&g:groups)sum+=g.size();if(sum!=static_cast<std::size_t>(n))return 2;
 std::printf("\"groups_calls\":%zu,\"groups_bytes\":%zu,\"groups_live_bytes\":%zu,\"groups_peak_bytes\":%zu,\"components\":%zu,",calls-old_calls,bytes-old_bytes,live-old_live,peak-old_live,groups.size());
 }}std::printf("\"live_delta_after_all_owners\":%zu}\n",live-before);if(live!=before)return 3;}

