 const int n=std::atoi(argv[1]),mode=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 std::mt19937 rng(61022);std::vector<std::pair<int,int>> balanced,star,randoms,queries;
 for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)balanced.emplace_back(i,i+step);
 for(int i=1;i<n;++i)star.emplace_back(0,i);
 for(int i=0;i<n;++i){randoms.emplace_back(int(rng()%n),int(rng()%n));queries.emplace_back(int(rng()%n),int(rng()%n));}
 UnionFind uf(n),initial(n);
 if(mode==2||mode==5||mode==8||mode==9||mode==10||mode==11)for(auto[a,b]:balanced){uf.unite(a,b);initial.unite(a,b);}
 if(mode==3||mode==7)for(int i=0;i<n;i+=4)for(int j=1;j<4&&i+j<n;++j)uf.unite(i,i+j);
 std::uint64_t checksum=0;
 const auto query=[&](UnionFind& target){for(auto[a,b]:queries)checksum+=target.same(a,b);};
 const auto run=[&](){
  if(mode==0||mode==1||mode==4){UnionFind local(n);const auto&edges=mode==0?balanced:mode==1?star:randoms;for(auto[a,b]:edges)checksum+=local.merge(a,b);query(local);checksum+=local.component_count();}
