  else if(mode==6||mode==7||mode==8){auto groups=uf.groups();checksum+=groups.size();for(const auto&g:groups)checksum+=g.size()+static_cast<unsigned>(g.back());}
  else if(mode==9){UnionFind local=initial;auto groups=local.groups();query(local);checksum+=groups.size();}
  else if(mode==10){for(auto[a,b]:queries)checksum+=static_cast<unsigned>(uf.root(a))+static_cast<unsigned>(uf.root(b));}
  else if(mode==11){for(auto[a,b]:queries)checksum+=uf.merge(a,b);}
 };
 run();checksum=0;
 const auto begin=std::chrono::steady_clock::now();for(int r=0;r<reps;++r)run();const auto end=std::chrono::steady_clock::now();
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),static_cast<std::uintmax_t>(checksum));
}

