#include SOURCE
#include <algorithm>
#include <iostream>
#include <numeric>
#include <random>
#include <stdexcept>
#include <vector>
int main(){std::mt19937 rng(61022);std::uint64_t checks=0;
for(int n=0;n<66;++n){UnionFind a(n);std::vector<int> c(n);std::iota(c.begin(),c.end(),0);
 for(int t=0;t<2000;++t){if(n==0)break;int x=int(rng()%n),y=int(rng()%n);
  if(rng()%3==0){bool changed=c[x]!=c[y];if(a.merge(x,y)!=changed)throw std::runtime_error("merge");int old=c[y],next=c[x];for(int&v:c)if(v==old)v=next;++checks;}
  else{if(a.same(x,y)!=(c[x]==c[y]))throw std::runtime_error("same");++checks;}
  if(t%17==0){auto g=a.groups();std::vector<std::vector<int>> expected;for(int i=0;i<n;++i){std::vector<int> row;for(int j=0;j<n;++j)if(c[j]==i)row.push_back(j);if(!row.empty())expected.push_back(row);}auto sorted=g;std::sort(sorted.begin(),sorted.end());std::sort(expected.begin(),expected.end());if(sorted!=expected||int(g.size())!=a.component_count())throw std::runtime_error("groups");++checks;
    for(int i=0;i<n;++i){int count=0;for(int v:c)count+=v==c[i];if(a.size(i)!=count)throw std::runtime_error("size");++checks;}}
 }if(n==0&&!a.groups().empty())throw std::runtime_error("empty");}
std::cout<<"PASS "<<checks<<'\n';}

