from pathlib import Path
p=Path(__file__).parent;p.mkdir(exist_ok=True);original=(p.parent/'baseline/DataStructure/union_find.cpp').read_text()
def put(name,s):(p/(name+'.hpp')).write_text(s)
put('baseline',original);put('control',original)
old='    bool same(int a, int b) { check(a); check(b); return leader_unchecked(a) == leader_unchecked(b); }'
same='''    bool same(int a, int b) {
        check(a); check(b);
        const int pa = param[a], pb = param[b];
        const int x = pa < 0 ? a : pa, y = pb < 0 ? b : pb;
        return x == y || leader_unchecked(x) == leader_unchecked(y);
    }'''
put('samefast',original.replace(old,same))
begin=original.index('    int leader_unchecked(int i) {');end=original.index('\npublic:',begin)
full='''    int leader_unchecked(int i) {
        int r = i;
        while (param[r] >= 0) r = param[r];
        while (i != r) { const int next = param[i]; param[i] = r; i = next; }
        return r;
    }'''
split='''    int leader_unchecked(int i) {
        while (param[i] >= 0) {
            const int p = param[i];
            if (param[p] < 0) return p;
            param[i] = param[p]; i = p;
        }
        return i;
    }'''
put('full',original[:begin]+full+original[end:]);put('split',original[:begin]+split+original[end:])
merge=original.replace('        a = leader_unchecked(a); b = leader_unchecked(b);','        if (a == b) return false;\n        a = leader_unchecked(a); b = leader_unchecked(b);')
put('same_merge',merge.replace(old,same))
begin=original.index('    std::vector<std::vector<int>> groups() {');end=original.index('\n};',begin)
groups='''    std::vector<std::vector<int>> groups() {
        std::vector<std::vector<int>> result;
        result.reserve(static_cast<std::size_t>(components_));
        if (components_ == size()) {
            for (int v = 0; v < size(); ++v) result.emplace_back(std::size_t{1}, v);
            return result;
        }
        if (components_ == 1) {
            const int root = leader_unchecked(0);
            result.emplace_back(param.size());
            for (int v = 0; v < size(); ++v) {
                if (v != root) param[v] = root;
                result[0][v] = v;
            }
            return result;
        }
        std::vector<int> leaders(param.size()), counts(param.size(), 0);
        for (int i = 0; i < size(); ++i) ++counts[leaders[i] = leader_unchecked(i)];
        for (int i = 0; i < size(); ++i) if (counts[i]) {
            const int count = counts[i];
            counts[i] = static_cast<int>(result.size());
            result.emplace_back(); result.back().reserve(count);
        }
        for (int i = 0; i < size(); ++i) result[counts[leaders[i]]].push_back(i);
        return result;
    }'''
put('groups',original[:begin]+groups+original[end:]);put('same_groups',(original[:begin]+groups+original[end:]).replace(old,same))

